    parts = x.split('/')
    components = [p for p in parts if p != '']

    stack = []
    for comp in components:
        if comp == '.':
            # Dot is the working-directory marker: it contributes nothing.
            continue
        if comp == '..':
            # Parent-directory marker. Pop the last real component if one exists;
            # otherwise the relative path refers to an ancestor outside the
            # current directory, so the '..' must be preserved.
            if stack and stack[-1] != '..':
                stack.pop()
            else:
                stack.append('..')
        else:
            # Regular component. The old filesystem is case blind, but no case
            # canonicalization is possible without a directory listing, so the
            # component is kept exactly as given.
            stack.append(comp)

    return stack
